                    // ✅ 检查当前阶段类型是否已触发过（每个阶段限一次）
                    // 使用 lib.phaseName 遍历所有阶段，找到当前所在的阶段
                    var currentPhaseName = null;
                    for (var i = 0; i < lib.phaseName.length; i++) {
                        var phase = lib.phaseName[i];
                        var evt = event.getParent(phase);
                        if (evt && evt.name === phase) {
                            currentPhaseName = phase;
                            break;
                        }
                    }
                    
                    if (!currentPhaseName) return false;
                    
                    // 检查这个阶段是否已经触发过
                    if (!player.storage.clanfufengRemake_phases) {
                        player.storage.clanfufengRemake_phases = {};
                    }
                    
                    var phaseKey = game.phaseNumber + '_' + player.phaseNumber + '_' + currentPhaseName;
                    if (player.storage.clanfufengRemake_phases[phaseKey]) {
                        return false;
                    }
                    
                    return event.cards && event.cards.length > 0;
