                    var color = get.color(card);
                    var otherColor = (color == 'red') ? 'black' : 'red';
                   
                    var otherCards = player.getCards('h', function(c) {
                      return get.color(c) == otherColor;
                    });
                   
                    if (otherCards.length == 0) {
                      event.finish();
                      return;
                    }
                   
