            "chi_fushui": {
                audio: "ext:custom:chi_fushui",
                trigger: {
                    player: "damageEnd",
                    global: "useCardAfter",
                },
                filter(event, player, name) {
                    if (name == "damageEnd") return true;
                    
                    // 检查是否有人响应了倞道修改后的牌
                    if (event.player != player) return false;
                    
                    const cardKey = event.card.cardid || get.translation(event.card);
                    if (!_status.chi_liangdao_active || !_status.chi_liangdao_active[cardKey]) return false;
                    
                    // 检查是否有人响应了
                    const respondList = event.getParent().respondList || [];
                    return respondList.length > 0;
                },
                direct: true,
                content() {
                    "step 0"
                    
                    player.logSkill("chi_fushui");
                    player.draw(2);
                    
                    // 检查哪些选项还未选择
                    if (!player.storage.chi_fushui_selected) player.storage.chi_fushui_selected = [];
                    
                    const options = [
                        ["使用限制", "①去掉“每回合限两次”"],
                        ["牌名限制", "②去掉“每轮每种牌名限一次”"],
                        ["增加花色", "③“牌名”平行选项增加“或花色”"],
                        ["永久修改", "④去掉“本次结算”（永久修改）"],
                        ["增加数字", "⑤“牌名”平行选项增加“或数字/+1”"],
                    ];
                    
                    const availableOptions = [];
                    const availableControls = [];
                    
                    for (const opt of options) {
                        if (!player.storage.chi_fushui_selected.includes(opt[0])) {
                            availableOptions.push(opt[1]);
                            availableControls.push(opt[0]);
                        }
                    }
                    
                    if (availableOptions.length == 0) {
                        // 所有选项都已选择，不应该到这里
                        event.finish();
                        return;
                    }
                    
                    event.availableControls = availableControls;
                    
                    player.chooseControl(availableControls)
                        .set("prompt", `覆水：选择一项（已选择${player.storage.chi_fushui_selected.length}/5次）`)
                        .set("choiceList", availableOptions)
                        .set("ai", () => {
                            // 优先选择去掉限制
                            if (availableControls.includes("去掉每回合限两次")) return "去掉每回合限两次";
                            if (availableControls.includes("去掉每轮每种牌名限一次")) return "去掉每轮每种牌名限一次";
                            if (availableControls.includes("永久修改")) return "永久修改";
                            return availableControls[0];
                        });
                    
                    "step 1"
                    const choice = result.control;
                    
                    if (!player.storage.chi_fushui_selected) player.storage.chi_fushui_selected = [];
                    player.storage.chi_fushui_selected.push(choice);
                    
                    switch(choice) {
                        case "使用限制":
                            player.storage.chi_liangdao_turnLimit = true;
                            game.log(player, "去掉了【倞道】的“每回合限两次”");
                            break;
                        case "牌名限制":
                            player.storage.chi_liangdao_roundLimit = true;
                            game.log(player, "去掉了【倞道】的“每轮每种牌名限一次”");
                            break;
                        case "增加花色":
                            player.storage.chi_liangdao_addSuit = true;
                            game.log(player, "为【倞道】增加了“或花色”选项");
                            break;
                        case "永久修改":
                            player.storage.chi_liangdao_permanent = true;
                            game.log(player, "【倞道】改为永久修改");
                            break;
                        case "增加数字":
                            player.storage.chi_liangdao_addNumber = true;
                            game.log(player, "为【倞道】增加了“或数字/+1”选项");
                            break;
                    }
                    
                    // ⭐⭐⭐ 关键：更新技能描述 ⭐⭐⭐
                    game.broadcastAll(function(player) {
                        if (lib.skill.chi_liangdao.dynamicTranslate) {
                            game.trySkillAudio("chi_liangdao", player);
                        }
                    }, player);
                    
                    player.updateMarks();
                    game.updateRoundNumber();
                    
                    // ⭐⭐⭐ 检查是否选完5个选项，立刻觉醒 ⭐⭐⭐
                    if (player.storage.chi_fushui_selected.length >= 5) {
                        game.log(player, "已选择5个【覆水】选项，开始觉醒");
                        
                        game.broadcastAll(function(player) {
                            player.$skill('倞道·觉醒', 'fire', 'metal');
                        }, player);
                        game.delayx();
                        
                        player.setAvatar("chi_yuji", "chi_yuji_burn");
                        player.awakenSkill("chi_fushui");
                        player.gainMaxHp();
                        var num = player.maxHp - player.hp;
                        if (num > 0) player.recover(num);
                        
                        // ⭐⭐⭐ 添加诣谛技能 ⭐⭐⭐
                        player.addSkill("chi_yidi");
                        game.log(player, "增加了1点体力上限并回复体力至上限，获得了技能【诣谛】");
                    }
                },
                "skill_id": "chi_fushui",
                "_priority": 0,
            },
