                if (event.cardNames.length == 0) {
                    game.log("没有可用的牌名");
                    event.finish();
                    return;
                }
                
                // ✅ 改成 chooseButton 显示牌的图片
                const list = event.cardNames.map(name => ['基本', '', name]);
                player.chooseButton(['千谆：选择要使用或打出的牌名', [list, 'vcard']], true)
                    .set("ai", (button) => {
                        return 1;
                    });
