                        const discardCards = Array.from(ui.discardPile.childNodes);
                        const allCards = pileCards.concat(discardCards);
                        
                        let targetCardCount = 0;
                        const cardDetails = {
                            fireSha: 0,
                            thunderSha: 0,
                            huogong: 0,
                            shandian: 0,
                            tiesuo: 0
                        };
                        
                        for (const card of allCards) {
                            const name = card.name;
                            const nature = card.nature;
                            
                            if (name == "sha" && nature == "fire") {
                                targetCardCount++;
                                cardDetails.fireSha++;
                            } else if (name == "sha" && nature == "thunder") {
                                targetCardCount++;
                                cardDetails.thunderSha++;
                            } else if (name == "huogong") {
                                targetCardCount++;
                                cardDetails.huogong++;
                            } else if (name == "shandian") {
                                targetCardCount++;
                                cardDetails.shandian++;
                            } else if (name == "tiesuo") {
                                targetCardCount++;
                                cardDetails.tiesuo++;
                            }
                        }
                        
                        const probabilityP = ((targetCardCount / 25) * 100).toFixed(2);
                        const probabilityQ = allCards.length > 0 ? ((targetCardCount / allCards.length) * 100).toFixed(2) : "0.00";
                        
                        let str = "<div style='text-align:left;'>";
