                        var basicCards = ['sha', 'shan', 'tao', 'jiu', 'wuzhong', 'juedou', 'huogong', 'jiedao', 'wuxie', 'wugu', 'taoyuan', 'nanman', 'wanjian', "shunshou", "guohe"];
                        
