                                let maxHp = player.maxHp;
                                
                                game.log(player, "交换手牌数", "#y" + handNum, "和体力上限", "#y" + maxHp);
                                
                                // 先调整体力上限
                                if (handNum > maxHp) {
                                    player.gainMaxHp(handNum - maxHp);
                                } else if (handNum < maxHp) {
                                    player.loseMaxHp(maxHp - handNum);
                                }
                                
                                // 再调整手牌数
                                let newHandNum = player.countCards('h');
